+import org.springframework.dao.DataAccessException;
+
+import java.util.function.Supplier;
+import java.util.stream.Stream;
+
+/** UC-002: Browse veterinarians and their specialties with infinite scrolling. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        Grid<Vet> grid = new Grid<>();
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : String.join(", ", vet.specialties()))
+                .setHeader("Specialties").setKey("specialties");
+        grid.setSizeFull();
+        grid.setItems(DataProvider.fromCallbacks(
+                query -> load(() -> this.repository.findPage(query.getOffset(), query.getLimit()), Stream.empty()),
+                query -> load(() -> this.repository.count(), 0)));
+
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+
+    private <T> T load(Supplier<T> query, T empty) {
+        try {
+            return query.get();
+        } catch (DataAccessException exception) {
+            // Lazy callbacks run after navigation too, so explicitly route failures
+            // through the same error handler used for navigation exceptions.
+            setVisible(false);
+            UI ui = UI.getCurrent();
+            ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                    ui.getInternals().getActiveViewLocation(), exception, NavigationTrigger.PROGRAMMATIC, null);
+            return empty;
+        }
+    }
+}
